def parse_row_clues(pattern):
    """Extract the sequence of # run lengths from a row pattern."""
    clues = []
    for match in re.finditer(r'#(\{(\d+)\})?', pattern):
        count = int(match.group(2)) if match.group(2) else 1
        clues.append(count)
    return clues


